import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, k = data[0], data[1], data[2]

    parent = list(range(n))
    size = [1] * n
    components = n
    roads = []
    water_cycle = False

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        nonlocal components
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        components -= 1
        return True

    pos = 3
    for _ in range(m):
        a, b, t = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        if t == 1:
            if not union(a, b):
                water_cycle = True
        else:
            roads.append((a, b))

    if water_cycle:
        print("N")
        return

    for a, b in roads:
        union(a, b)

    print("S" if m - n + components <= k else "N")

if __name__ == "__main__":
    main()
